<script>
document.getElementById('aiTrainingTest').addEventListener('submit',async function(event){event.preventDefault();const status=document.getElementById('aiTrainingTestStatus'),answer=document.getElementById('aiTrainingTestAnswer');status.textContent='Checking approved knowledge and configured provider…';answer.style.display='none';try{const response=await fetch(@json(route('admin.ai_training.test')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:JSON.stringify({question:document.getElementById('trainingTestQuestion').value,language:document.getElementById('trainingTestLanguage').value})});const data=await response.json();if(!response.ok)throw new Error(data.message||'Test failed');status.textContent='Source: '+(data.response_source||'Safety rule')+(data.unanswered?' · Unanswered':'');answer.textContent=data.answer;answer.style.display='block'}catch(error){status.textContent=error.message}});
</script>
